const name = String(inputs.visitorName || '').trim();
const email = String(inputs.visitorEmail || '').trim();
const host = String(inputs.visitorHost || '');
const photoUrl = String(inputs.visitorPhoto || '');
const hosts = { alex: 'Alex Morgan - Operations', jamie: 'Jamie Chen - Engineering', sam: 'Sam Rivera - Facilities' };
let problem = '';
if (!name || name.length > 72 || /[\u0000-\u001f\u007f]/u.test(name)) problem = 'Enter your name (up to 72 characters).';
else if (email.length > 100 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/u.test(email)) problem = 'Enter a valid email address (up to 100 characters).';
else if (!Object.hasOwn(hosts, host)) problem = 'Choose the person you are visiting.';
else { try { const url = new URL(photoUrl); if (url.protocol !== 'blob:' || url.origin !== location.origin) problem = 'Start the camera and capture your photo first.'; } catch { problem = 'Start the camera and capture your photo first.'; } }
app.state.set('screen', 'error', problem);
if (problem) return;
app.state.set('screen', 'busy', true);
const signal = AbortSignal.any([app.signal, AbortSignal.timeout(20000)]);
// Return immediately: the component owns this bounded asynchronous job until unmount.
void (async () => {
  let bitmap;
  let badgeUrl = '';
  try {
    const photoResponse = await fetch(photoUrl, { signal });
    if (!photoResponse.ok) throw new Error('The captured photo is unavailable. Retake it and try again.');
    const photo = await photoResponse.blob();
    if (photo.type !== 'image/png' || !photo.size || photo.size > 2000000) throw new Error('Retake the photo and try again.');
    bitmap = await createImageBitmap(photo);
    const canvas = document.createElement('canvas');
    canvas.width = 192; canvas.height = 192;
    const context = canvas.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('This browser cannot prepare the badge photo.');
    context.fillStyle = '#ffffff'; context.fillRect(0, 0, 192, 192);
    const side = Math.min(bitmap.width, bitmap.height);
    context.drawImage(bitmap, (bitmap.width - side) / 2, (bitmap.height - side) / 2, side, side, 0, 0, 192, 192);
    const pixels = context.getImageData(0, 0, 192, 192).data;
    // Four-by-four ordered dithering preserves photo detail on a monochrome label.
    const thresholds = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
    let graphic = '';
    for (let y = 0; y < 192; y++) for (let column = 0; column < 24; column++) {
      let byte = 0;
      for (let bit = 0; bit < 8; bit++) {
        const x = column * 8 + bit, i = (y * 192 + x) * 4;
        const gray = .2126 * pixels[i] + .7152 * pixels[i + 1] + .0722 * pixels[i + 2];
        const alpha = pixels[i + 3] / 255;
        if (gray * alpha + 255 * (1 - alpha) < (thresholds[(y % 4) * 4 + x % 4] + .5) * 16) byte |= 128 >> bit;
      }
      graphic += byte.toString(16).padStart(2, '0').toUpperCase();
    }
    bitmap.close(); bitmap = undefined;
    // Encode every UTF-8 byte; visitor text cannot introduce ZPL commands.
    const field = value => Array.from(new TextEncoder().encode(value), byte => '_' + byte.toString(16).padStart(2, '0').toUpperCase()).join('');
    const zpl = '^XA^CI28^PW812^LL609^LH0,0' +
      '^FO32,26^A0N,44,44^FDVISITOR^FS^FO32,88^GB748,3,3^FS' +
      '^FO32,120^A0N,18,18^FDNAME^FS^FO32,152^A0N,34,34^FB470,3,5,L,0^FH_^FD' + field(name) + '^FS' +
      '^FO558,120^GB208,208,2^FS^FO566,128^GFA,4608,4608,24,' + graphic + '^FS' +
      '^FO32,310^A0N,18,18^FDVISITING^FS^FO32,340^A0N,28,28^FB490,2,4,L,0^FH_^FD' + field(hosts[host]) + '^FS' +
      '^FO32,430^A0N,18,18^FDEMAIL^FS^FO32,460^A0N,23,23^FB748,2,4,L,0^FH_^FD' + field(email) + '^FS' +
      '^FO32,548^GB748,2,2^FS^FO32,566^A0N,18,18^FDVisitor check-in workshop^FS^XZ';
    if (signal.aborted) throw signal.reason;
    const response = await fetch('https://api.labelary.com/v1/printers/8dpmm/labels/4x3/0/', {
      method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'image/png' },
      body: zpl, credentials: 'omit', referrerPolicy: 'no-referrer', redirect: 'error', signal,
    });
    if (!response.ok) throw new Error(response.status === 429 ? 'Labelary is busy or its daily limit was reached. Wait, then try again.' : 'Labelary could not render the badge (HTTP ' + response.status + '). Try again.');
    if (!/^image\/png(?:;|$)/i.test(response.headers.get('content-type') || '')) throw new Error('Labelary returned an unexpected image format. Try again.');
    const badge = await response.blob();
    if (!badge.size || badge.size > 2000000) throw new Error('Labelary returned an invalid badge image. Try again.');
    const signature = new Uint8Array(await badge.slice(0, 8).arrayBuffer());
    if (![137,80,78,71,13,10,26,10].every((byte, index) => signature[index] === byte)) throw new Error('Labelary returned an invalid badge image. Try again.');
    if (app.signal.aborted) return;
    if (signal.aborted) throw signal.reason;
    badgeUrl = URL.createObjectURL(badge);
    app.state.set('screen', 'badgeUrl', badgeUrl);
    app.state.set('screen', 'badgeReady', true);
    badgeUrl = '';
  } catch (error) {
    if (!app.signal.aborted) app.state.set('screen', 'error', signal.aborted ? 'Badge rendering timed out. Check your connection and try again.' : error instanceof Error && error.name !== 'TypeError' ? error.message : 'Cannot reach Labelary. Check your internet connection and try again.');
  } finally {
    bitmap?.close();
    if (badgeUrl) URL.revokeObjectURL(badgeUrl);
    if (!app.signal.aborted) app.state.set('screen', 'busy', false);
  }
})();

